require_once __DIR__ . '/bootstrap.php'; require_admin(); header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="mamidav-orders-'.date('Y-m-d').'.csv"');$where=[];$args=[];foreach(['payment_status','order_status','order_source','payment_method'] as $field){if(!empty($_GET[$field])){$where[]="$field=?";$args[]=$_GET[$field];}}if(!empty($_GET['date_from'])){$where[]='created_at>=?';$args[]=$_GET['date_from'].' 00:00:00';}if(!empty($_GET['date_to'])){$where[]='created_at<=?';$args[]=$_GET['date_to'].' 23:59:59';}if(!empty($_GET['q'])){$where[]='(reference LIKE ? OR customer_name LIKE ? OR customer_email LIKE ? OR customer_phone LIKE ? OR payment_reference LIKE ?)';for($i=0;$i<5;$i++)$args[]='%'.$_GET['q'].'%';}$pdo=get_db();$rows=$pdo->prepare('SELECT reference,customer_name,customer_email,customer_phone,total,currency,order_source,payment_method,payment_reference,payment_status,order_status,created_at,updated_at,notes FROM orders'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC');$rows->execute($args);$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Reference','Customer','Email','Phone','Total','Currency','Source','Payment Method','Payment Reference','Payment Status','Order Status','Created','Updated','Notes']);while($row=$rows->fetch())fputcsv($out,$row);fclose($out);
